/* Mintora Blueprint: the licensed studio for plugins (storefronts, hubs, the dashboard) and design systems */
const licensed=()=>!!(S&&S.bp.license);
const TARGETS={page:['Storefront','page','Runs on product pages'],hub:['Hub','hub','Runs inside hubs'],app:['Dashboard','dash','Adds widgets to your dashboard']};
const TRIGGERS={page:[['load','When the page loads'],['purchase','After a purchase']],hub:[['join','When someone joins'],['command','On a slash command'],['publish','When a product goes live']],app:[['always','Always on']]};
const ACTIONS={
 banner:{t:'page',n:'Top banner',ic:'mega',f:[['text','Text','Launch week: everything 20% off'],['tone','Tone','accent',['accent','dark']]]},
 countdown:{t:'page',n:'Countdown',ic:'clock',f:[['label','Label','Launch price ends in'],['hours','Hours','48','num']]},
 discount:{t:'page',n:'Discount code',ic:'tag',f:[['code','Code','LAUNCH20'],['pct','Percent off','20','num']]},
 proof:{t:'page',n:'Social proof',ic:'users',f:[['text','Text','{n} people bought this week']]},
 sticky:{t:'page',n:'Sticky buy bar',ic:'cart',f:[['text','Text','Ready when you are']]},
 welcome:{t:'hub',n:'Welcome message',ic:'wave',f:[['message','Message','Welcome, {name}! Start in #general and say hi.']]},
 autorole:{t:'hub',n:'Give a role',ic:'shield',f:[['role','Role','Member']]},
 command:{t:'hub',n:'Slash command',ic:'term',f:[['cmd','Command','/links'],['reply','Reply','Docs, templates and the roadmap: mintora.shop/{hub}']]},
 announce:{t:'hub',n:'Announcement',ic:'mega',f:[['text','Text','New on the shelf: {product}. Have a look!']]},
 widget:{t:'app',n:'Metric widget',ic:'chart',f:[['metric','Metric','revenue',['revenue','orders','visitors','conversion','score','goal']],['label','Label','Revenue today'],['goal','Goal (for goal tracker)','10000','num']]}};
IC.wave=IC.chat;
const TEMPLATES=[
 {n:'Launch countdown',d:'A banner with a live countdown to the end of launch pricing.',target:'page',trigger:'load',actions:[{type:'banner',text:'Launch week pricing',tone:'accent'},{type:'countdown',label:'Ends in',hours:48}]},
 {n:'Discount code',d:'Shows a code under the button and applies it at checkout.',target:'page',trigger:'load',actions:[{type:'discount',code:'LAUNCH20',pct:20}]},
 {n:'Social proof',d:'A live line with how many people bought this week.',target:'page',trigger:'load',actions:[{type:'proof',text:'{n} people bought this week'}]},
 {n:'Sticky buy bar',d:'A buy bar that follows the reader down the page.',target:'page',trigger:'load',actions:[{type:'sticky',text:'Ready when you are'}]},
 {n:'Welcome bot',d:'Greets every new member by name.',target:'hub',trigger:'join',actions:[{type:'welcome',message:'Welcome, {name}! Start in #general and say hi.'}]},
 {n:'Auto role',d:'Gives new members a role the moment they join.',target:'hub',trigger:'join',actions:[{type:'autorole',role:'Customer'}]},
 {n:'Slash command',d:'Answers a custom /command in any channel.',target:'hub',trigger:'command',actions:[{type:'command',cmd:'/links',reply:'Docs, templates and the roadmap: mintora.shop/{hub}'}]},
 {n:'Launch announcer',d:'Posts in your hubs when a product goes live.',target:'hub',trigger:'publish',actions:[{type:'announce',text:'New on the shelf: {product}. Have a look!'}]},
 {n:'Revenue goal',d:'A dashboard widget that tracks a monthly goal.',target:'app',trigger:'always',actions:[{type:'widget',metric:'goal',label:'Monthly goal',goal:10000}]}];
function actSummary(x){return x.actions.map(a=>{const A=ACTIONS[a.type];return A?A.n+(a.type==='countdown'?` ${a.hours}h`:a.type==='discount'?` ${a.code}`:a.type==='command'?` ${a.cmd}`:''):a.type}).join(' · ')||'No actions yet'}
function bpLog(x,msg,lvl='ok'){x.runs=(x.runs||0)+1;S.bp.logs.unshift({at:Date.now(),pid:x.id,name:x.name,msg,lvl});if(S.bp.logs.length>200)S.bp.logs.length=200;saveSoon()}
/* ---- plugins at work ---- */
function pagePlugins(p){const out={banner:'',proof:'',code:'',sticky:'',discount:null};if(!licensed())return out;
 (p.page.plugins||[]).map(id=>S.bp.plugins.find(x=>x.id===id)).filter(x=>x&&x.status==='published'&&x.target==='page').forEach(x=>x.actions.forEach(a=>{
  if(a.type==='banner'){const cd=x.actions.find(b=>b.type==='countdown');out.banner+=`<div class="pl-banner ${a.tone==='dark'?'dark':''}">${ic('bolt','s')}<span>${esc(a.text)}</span>${cd?`<span>${esc(cd.label)}</span><span class="cd" data-end="${cdEnd(x,cd)}">--:--:--</span>`:''}</div>`}
  if(a.type==='countdown'&&!x.actions.some(b=>b.type==='banner'))out.banner+=`<div class="pl-banner dark">${ic('clock','s')}<span>${esc(a.label)}</span><span class="cd" data-end="${cdEnd(x,a)}">--:--:--</span></div>`;
  if(a.type==='proof'){const n=ordersIn(7,0,p.id).length;out.proof+=`<div class="pl-proof"><i></i>${esc(fill(a.text,{n:Math.max(n,1)}))}</div>`}
  if(a.type==='discount'){out.discount={code:a.code,pct:+a.pct||0};out.code+=`<div class="pl-code">${ic('tag','s')}Use <code>${esc(a.code)}</code> for ${+a.pct||0}% off</div>`}
  if(a.type==='sticky')out.sticky=`<div class="pl-sticky"><b style="font-family:var(--sfont)">${esc(p.name)}</b><span style="color:var(--smu);font-size:13px">${esc(a.text)}</span><button class="sbtn" style="margin-left:auto;height:38px" onclick="checkout('${p.id}')">${money(p.price)}</button></div>`}));return out}
function cdEnd(x,a){const len=(+a.hours||24)*3600e3,start=x.published||x.updated||Date.now();let end=start+len;while(end<Date.now())end+=len;return end}
let _cdT=0;function startCountdowns(){clearInterval(_cdT);const tick=()=>{const L=$$('.cd[data-end]');if(!L.length){clearInterval(_cdT);return}L.forEach(el=>{const s=Math.max(0,Math.floor((+el.dataset.end-Date.now())/1000));el.textContent=[Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(v=>String(v).padStart(2,'0')).join(':')})};tick();_cdT=setInterval(tick,1000)}
function pluginEvent(kind,ctx={}){if(!licensed())return;S.bp.plugins.filter(x=>x.status==='published').forEach(x=>{
 if(x.target==='page'&&ctx.pid&&prod(ctx.pid)?.page.plugins.includes(x.id)){if(kind==='load')x.runs=(x.runs||0)+1;if(kind==='purchase')bpLog(x,`Purchase on ${prod(ctx.pid).name}`)}
 if(x.target==='hub'&&x.trigger==='publish'&&kind==='publish'){const p=prod(ctx.pid);S.hubs.filter(h=>h.plugins.includes(x.id)).forEach(h=>{const ch=h.channels.find(c=>c.type==='announce')||h.channels[0];x.actions.filter(a=>a.type==='announce').forEach(a=>{ch.msgs.push({id:uid('m'),who:'bot',bot:true,botName:x.name,text:fill(a.text,{product:p.name,hub:h.name}),t:Date.now()});ch.unread=(ch.unread||0)+1;bpLog(x,`Announced ${p.name} in ${h.name}`)})})}})}
function pluginWidgets(){if(!licensed())return'';return S.bp.plugins.filter(x=>x.status==='published'&&x.target==='app'&&x.dash!==false).flatMap(x=>x.actions.filter(a=>a.type==='widget').map(a=>{
 const m=a.metric,L=m==='goal'?ordersIn(new Date().getDate()):ordersIn(1);let v,sub='';
 if(m==='revenue'){v=money(revOf(L))}else if(m==='orders'){v=nfmt(L.length)}else if(m==='visitors'){v=short(viewsIn(null,1))}else if(m==='conversion'){const vv=viewsIn(null,1);v=pct(vv?L.length/vv:0,2)}else if(m==='score'){v=perfScore().score+'/100'}else{const r=revOf(L),g=+a.goal||1;v=money(r);sub=`<div class="pbar" style="margin-top:10px"><i style="width:${Math.min(100,r/g*100)}%"></i></div><div class="d">${pct(Math.min(1,r/g),0)} of ${money(g)} this month</div>`}
 return`<div class="card kpi" style="border-style:dashed"><div class="l">${ic('plug')} ${esc(a.label)} <span class="badge vio" style="margin-left:auto;height:18px;font-size:10px">${esc(x.name)}</span></div><div class="v">${v}</div>${sub||'<div class="d">Live from your plugin</div>'}</div>`})).join('')}
/* ---- license ---- */
function keyCheck(k){return(hashN(k)%46656).toString(36).toUpperCase().padStart(3,'0')}
function makeKey(){const a=Math.random().toString(36).slice(2,6).toUpperCase().padEnd(4,'X'),b=Math.random().toString(36).slice(2,6).toUpperCase().padEnd(4,'Z');return`MNT-BP-${a}-${b}-${keyCheck(a+b)}`}
function keyOK(k){const m=/^MNT-BP-([A-Z0-9]{4})-([A-Z0-9]{4})-([A-Z0-9]{3})$/.exec(String(k).trim().toUpperCase());return!!m&&keyCheck(m[1]+m[2])===m[3]}
function grantLicense(tier,key){S.bp.license={tier,key:key||makeKey(),at:Date.now(),seats:tier==='studio'?5:1};act('plugin',`Blueprint ${tier} license activated`);notify('Blueprint is unlocked','key','bp');save()}
function buyLicense(){if(licensed())return;if(!spend(2000,'Blueprint license (Solo)'))return;grantLicense('solo');toast('Blueprint unlocked','key');go('bp')}
function enterKey(){const v=$('#bpKey').value.trim().toUpperCase();if(!keyOK(v)){$('#bpKey').parentNode.style.borderColor='#FF8A93';$('#bpKeyE').textContent='That key is not valid. It looks like MNT-BP-XXXX-XXXX-XXX.';return}grantLicense('studio',v);toast('License key accepted','key');go('bp')}
function bpGate(what){return`<div class="page"><div class="lic bpframe" style="max-width:720px;margin:40px auto;text-align:center;padding:44px">${bpMark(64)}<h1 style="margin:18px 0 8px;font:500 26px var(--f-mono)">${esc(what)} needs a license</h1><p style="color:#A8BFE8;max-width:460px;margin:0 auto 22px">Blueprint is the builder side of Mintora: plugins for storefronts, hubs and your dashboard, and design systems made from scratch.</p><a class="btn mint lg" href="#/bp/license">${ic('key','s')} Get a license</a></div></div>`}
/* ---- overview ---- */
PAGES.bp={crumbs:(s,id)=>{const base=[['Blueprint','#/bp']];if(!s)return[['Blueprint']];if(s==='plugin')return[...base,['Plugins','#/bp/plugins'],[S.bp.plugins.find(x=>x.id===id)?.name||'Plugin']];if(s==='design')return[...base,['Designs','#/bp/designs'],[design(id)?.name||'Design']];return[...base,[{plugins:'Plugins',designs:'Designs',license:'License',docs:'Reference'}[s]||s]]},
view(s,id){if(s==='license')return bpLicense();if(s==='docs')return bpDocs();if(!licensed()&&s)return bpGate(s==='plugin'||s==='plugins'?'Plugin Studio':'Design Studio');
 if(s==='plugins')return bpPlugins();if(s==='plugin')return pluginStudio(id);if(s==='designs')return bpDesigns();if(s==='design')return designStudio(id);return bpHome()},
after(s,id){segInit();if(s==='plugin')studioAfter(id);if(s==='design')designAfter(id);if(!s)startCountdowns()}};
function bpHome(){const L=licensed(),P=S.bp.plugins,inst=sum(P.map(x=>(x.installs||0)+(x.hubInstalls||0)+(x.target==='app'&&x.status==='published'?1:0))),runs=sum(P.map(x=>x.runs||0));
 return`<div class="page"><div class="grid g12" style="align-items:stretch">
 <div class="card span8 bpframe" style="padding:30px;position:relative;overflow:hidden"><div class="eyebrow">${ic('bp','s')} Mintora Blueprint ${L?`· ${esc(S.bp.license.tier.toUpperCase())} LICENSE`:''}</div>
  <h1 style="font:500 34px/1.15 var(--f-mono);letter-spacing:-.02em;max-width:540px">Draw the parts of Mintora that are yours.</h1><p style="color:var(--ink2);max-width:520px;margin:12px 0 22px">Plugins that run on your storefronts, inside your hubs and on your dashboard. Design systems you build from scratch and apply anywhere.</p>
  <div class="row">${L?`<button class="btn mint" onclick="newPlugin()">${ic('plug','s')} New plugin</button><button class="btn" onclick="newDesign()">${ic('palette','s')} New design</button>`:`<a class="btn mint lg" href="#/bp/license">${ic('key','s')} Get a license</a>`}<a class="btn ghost" href="#/bp/docs">${ic('code','s')} Reference</a></div>
  <div style="position:absolute;right:28px;top:26px;width:190px;height:190px">${bpSchematicMark()}</div></div>
 <div class="card span4" style="padding:20px"><div class="lbl" style="margin-bottom:14px;font-family:var(--f-mono);font-weight:500;letter-spacing:.08em;text-transform:uppercase;font-size:11px;color:var(--mint)">Status</div>
  ${[['License',L?S.bp.license.tier.toUpperCase():'NONE'],['Plugins',P.length],['Published',P.filter(x=>x.status==='published').length],['Installs',inst],['Runs',nfmt(runs)],['Designs',S.bp.designs.length]].map(([k,v])=>`<div class="row" style="padding:7px 0;border-bottom:1px dashed var(--line);font-family:var(--f-mono);font-size:13px"><span style="color:var(--muted)">${k}</span><b style="margin-left:auto;font-weight:500">${v}</b></div>`).join('')}</div></div>
 <h3 class="mt2" style="margin-bottom:12px">How it fits together</h3><div class="card" style="padding:18px">${bpSystem()}</div>
 <div class="grid g12 mt2"><div class="card span7"><div class="ch"><h3>Start from a template</h3><a class="acts btn ghost sm" href="#/bp/plugins">All plugins ${ic('right','s')}</a></div><div class="lst">${TEMPLATES.slice(0,5).map((t,i)=>`<div class="li click" onclick="${L?`newPlugin(${i})`:"go('bp/license')"}"><span style="width:32px;height:32px;border-radius:8px;display:grid;place-items:center;border:1px solid var(--line2);color:var(--mint)">${ic(TARGETS[t.target][1],'s')}</span><div class="grow"><b style="font-family:var(--f-mono);font-weight:500">${esc(t.n)}</b><div class="sub">${esc(t.d)}</div></div>${ic(L?'plus':'lock','s')}</div>`).join('')}</div></div>
 <div class="card span5"><div class="ch"><h3>Console</h3><span class="acts xs faint mono">${S.bp.logs.length} events</span></div><div class="cb"><div class="console">${S.bp.logs.slice(0,14).map(l=>`<div><span class="t">${ftime(l.at)}</span> <span class="${l.lvl}">●</span> <b>${esc(l.name)}</b> ${esc(l.msg)}</div>`).join('')||'<span class="t">// Plugin runs and test results show up here.</span>'}</div></div></div></div></div>`}
function bpSchematicMark(){return`<svg viewBox="0 0 200 200" fill="none" stroke-linecap="round" stroke-linejoin="round" style="width:100%;height:100%"><g stroke="#7FE3FF" stroke-width=".8" opacity=".5" stroke-dasharray="3 3"><circle cx="100" cy="100" r="80"/><path d="M100 4V196M4 100H196"/><path d="M30 60H170M30 140H170"/></g>
 <g transform="translate(36 36) scale(4)"><path d="${MARK.hex}" stroke="#EAF1FF" stroke-width=".5"/><path d="${MARK.m}" stroke="#7FE3FF" stroke-width=".5"/><circle cx="26.8" cy="9.4" r=".7" fill="#7FE3FF"/></g>
 <g font-family="JetBrains Mono,monospace" font-size="7" fill="#7FE3FF"><text x="104" y="12">R 80</text><text x="150" y="56">60°</text><text x="6" y="96">Ø 160</text></g><path d="M100 100L157 43" stroke="#7FE3FF" stroke-width=".8"/></svg>`}
function bpSystem(){const box=(x,y,w,t,s,c)=>`<g transform="translate(${x} ${y})"><rect width="${w}" height="64" rx="8" fill="rgba(9,33,79,.9)" stroke="${c}" stroke-width="1.4"/><text x="14" y="26" font-family="JetBrains Mono,monospace" font-size="13" fill="#EAF1FF">${t}</text><text x="14" y="46" font-family="JetBrains Mono,monospace" font-size="10.5" fill="#8FA9D8">${s}</text></g>`;
 return`<svg viewBox="0 0 980 230" style="width:100%;height:auto;display:block"><g stroke="rgba(127,227,255,.7)" stroke-width="1.4" fill="none" stroke-dasharray="6 5" style="animation:flow 1.2s linear infinite"><path d="M210 115H330"/><path d="M530 115C580 115 580 50 640 50"/><path d="M530 115H640"/><path d="M530 115C580 115 580 180 640 180"/></g>
 ${box(10,83,200,'mintora.events','purchase · join · publish','#7FE3FF')}${box(330,83,200,'your plugin','trigger → actions','#B6A8FF')}${box(640,18,320,'storefronts','banner · countdown · code · bar','#7DF0B8')}${box(640,83,320,'hubs','welcome · roles · /commands','#7DF0B8')}${box(640,148,320,'dashboard','metric and goal widgets','#7DF0B8')}</svg>`}
/* ---- plugins ---- */
function bpPlugins(){const P=S.bp.plugins;return`<div class="page"><div class="ph"><div class="grow"><div class="eyebrow">${ic('plug','s')} Plugin Studio</div><h1>Plugins</h1><p>Each plugin is a trigger and a list of actions, with a target where it runs.</p></div><div class="acts"><button class="btn mint" onclick="newPlugin()">${ic('plus','s')} From scratch</button></div></div>
 ${P.length?`<div class="pgrid" style="grid-template-columns:repeat(auto-fill,minmax(300px,1fr))">${P.map(x=>`<div class="card hov bpframe" style="padding:16px" onclick="go('bp/plugin/${x.id}')"><div class="row"><span style="width:34px;height:34px;border-radius:9px;display:grid;place-items:center;border:1px solid var(--line2);color:var(--mint)">${ic(TARGETS[x.target][1],'s')}</span><div class="grow"><b style="font:500 15px var(--f-mono)">${esc(x.name)}</b><div class="xs muted mono">v${x.version} · ${TARGETS[x.target][0]}</div></div><span class="badge ${x.status==='published'?'live':'draft'}"><i class="bd"></i>${x.status}</span></div>
  <p class="muted sm" style="margin:12px 0">${esc(x.desc||actSummary(x))}</p><div class="row xs mono muted"><span>${esc(TRIGGERS[x.target].find(t=>t[0]===x.trigger)?.[1]||x.trigger)}</span><span style="margin-left:auto">${nfmt(x.runs||0)} runs</span></div></div>`).join('')}</div>`:`<div class="card"><div class="empty">${figure('build',{acc:'#7FE3FF'})}<b>No plugins yet</b><p>Start from a template below or from scratch.</p></div></div>`}
 <h3 class="mt2" style="margin-bottom:12px">Templates</h3><div class="grid g3">${TEMPLATES.map((t,i)=>`<button class="card hov" style="padding:16px;text-align:left" onclick="newPlugin(${i})"><div class="row" style="margin-bottom:8px">${ic(TARGETS[t.target][1],'s')}<span class="xs mono" style="color:var(--mint)">${TARGETS[t.target][0].toUpperCase()}</span></div><b style="font:500 14px var(--f-mono)">${esc(t.n)}</b><p class="muted sm" style="margin:6px 0 0">${esc(t.d)}</p></button>`).join('')}</div></div>`}
function newPlugin(i){if(!licensed()){go('bp/license');return}const t=i!=null?TEMPLATES[i]:{n:'Untitled plugin',d:'',target:'page',trigger:'load',actions:[]};const x={id:uid('pl'),name:t.n,desc:t.d,target:t.target,trigger:t.trigger,actions:JSON.parse(JSON.stringify(t.actions)),status:'draft',version:'0.1.0',created:Date.now(),updated:Date.now(),runs:0,installs:0};S.bp.plugins.unshift(x);save();go('bp/plugin/'+x.id)}
/* the studio: form on the left, schematic and manifest in the middle, preview and install on the right */
let PS={tab:'manifest'};
function manifest(x){return JSON.stringify({name:x.name,version:x.version,description:x.desc||'',target:x.target,trigger:x.trigger,actions:x.actions},null,2)}
function pluginStudio(id){const x=S.bp.plugins.find(p=>p.id===id);if(!x)return`<div class="page"><div class="empty"><b>Plugin not found</b><a class="btn" href="#/bp/plugins">Back</a></div></div>`;
 return`<div class="page" style="max-width:none;padding:20px 24px 40px"><div class="row" style="margin-bottom:16px"><span style="width:38px;height:38px;border-radius:10px;display:grid;place-items:center;border:1px solid var(--line2);color:var(--mint)">${ic('plug')}</span><div><h1 style="font-size:20px">${esc(x.name)}</h1><div class="xs mono muted">${x.id} · v${x.version} · updated ${ago(x.updated)}</div></div><span class="badge ${x.status==='published'?'live':'draft'}" style="margin-left:8px"><i class="bd"></i>${x.status}</span>
 <div class="row" style="margin-left:auto"><button class="btn" onclick="testPlugin('${id}')">${ic('play','s')} Test run</button><button class="btn ghost danger" onclick="delPlugin('${id}')">${ic('trash','s')}</button><button class="btn mint" onclick="publishPlugin('${id}')">${ic('rocket','s')} ${x.status==='published'?'Publish update':'Publish'}</button></div></div>
 <div class="grid" style="grid-template-columns:310px minmax(0,1fr);gap:16px;align-items:start">
 <div class="card" style="padding:16px;position:sticky;top:0" id="psF">${studioForm(x)}</div>
 <div class="col" style="gap:16px;min-width:0"><div class="card bpframe" style="padding:16px"><div class="row" style="margin-bottom:10px"><b style="font:500 13px var(--f-mono)">SCHEMATIC</b><span class="xs mono faint" style="margin-left:auto">trigger → actions → target</span></div><div id="psN">${schematic(x)}</div></div>
  <div class="grid" style="grid-template-columns:minmax(0,1fr) 320px;gap:16px;align-items:start"><div class="card" style="padding:0;overflow:hidden"><div class="tabs" style="margin:0;padding:0 12px">${[['manifest','manifest.json'],['console','Console'],['code','plugin.js']].map(([k,n])=>`<button class="${PS.tab===k?'on':''}" data-pst="${k}" style="font-family:var(--f-mono);font-weight:500;font-size:12.5px">${n}</button>`).join('')}<span id="psErr" class="xs mono" style="margin-left:auto;align-self:center;color:#7DF0B8;max-width:60%;text-align:right">✓ valid</span></div>
  <div style="padding:12px" id="psT">${studioTab(x)}</div></div>
  <div class="col" style="gap:16px"><div class="card" style="padding:16px"><b style="font:500 13px var(--f-mono)">PREVIEW</b><div style="margin-top:12px" id="psP">${pluginPreview(x)}</div></div>
  <div class="card" style="padding:16px"><b style="font:500 13px var(--f-mono)">INSTALL</b><div style="margin-top:10px" id="psI">${installList(x)}</div></div></div></div></div></div></div>`}
function studioForm(x){const acts=Object.entries(ACTIONS).filter(([,a])=>a.t===x.target);
 return`<div class="field"><label>Name</label><input class="inp" data-pf="name" value="${esc(x.name)}"></div><div class="field"><label>Description</label><textarea class="inp" data-pf="desc" style="min-height:60px">${esc(x.desc||'')}</textarea></div>
 <div class="field"><label>Runs on</label><div class="chips">${Object.entries(TARGETS).map(([k,[n,i]])=>`<button class="chip ${x.target===k?'on':''}" data-tgt="${k}">${ic(i,'s')} ${n}</button>`).join('')}</div></div>
 <div class="field"><label>Trigger</label><select class="inp" data-pf="trigger">${TRIGGERS[x.target].map(([k,n])=>`<option value="${k}" ${x.trigger===k?'selected':''}>${n}</option>`).join('')}</select></div>
 <div class="lbl" style="margin:4px 0 8px">Actions</div>${x.actions.map((a,i)=>{const A=ACTIONS[a.type];if(!A)return'';return`<div style="border:1px solid var(--line2);border-radius:10px;padding:10px;margin-bottom:8px"><div class="row" style="margin-bottom:8px">${ic(A.ic,'s')}<b class="sm">${A.n}</b><button class="ibtn" style="margin-left:auto;width:24px;height:24px" data-rma="${i}" aria-label="Remove action">${ic('x','s')}</button></div>
  ${A.f.map(([k,n,def,opt])=>Array.isArray(opt)?`<select class="inp" style="height:32px;margin-bottom:6px" data-ai="${i}" data-ak="${k}">${opt.map(o=>`<option ${a[k]===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input class="inp" style="height:32px;margin-bottom:6px" placeholder="${esc(n)}" ${opt==='num'?'type="number"':''} data-ai="${i}" data-ak="${k}" value="${esc(a[k]??'')}" aria-label="${esc(n)}">`).join('')}</div>`}).join('')}
 <select class="inp" id="psAdd"><option value="">+ Add an action…</option>${acts.map(([k,a])=>`<option value="${k}">${a.n}</option>`).join('')}</select>
 <div class="xs muted" style="margin-top:10px">Placeholders: <code>{name}</code> <code>{hub}</code> <code>{product}</code> <code>{n}</code></div>`}
function schematic(x){const tl=TRIGGERS[x.target].find(t=>t[0]===x.trigger)?.[1]||x.trigger,n=Math.max(1,x.actions.length),H=Math.max(200,n*108+20),tg=x.target==='page'?S.products.filter(p=>p.page.plugins.includes(x.id)).map(p=>p.name):x.target==='hub'?S.hubs.filter(h=>h.plugins.includes(x.id)).map(h=>h.name):['Dashboard'];
 const ay=i=>12+i*108,ty=H/2-40;
 return`<div class="nodes" style="height:${H}px"><svg class="wires" viewBox="0 0 900 ${H}" preserveAspectRatio="none">${x.actions.map((_,i)=>`<path d="M250 ${H/2}C300 ${H/2} 300 ${ay(i)+34} 350 ${ay(i)+34}"/><path d="M570 ${ay(i)+34}C620 ${ay(i)+34} 620 ${H/2} 670 ${H/2}"/>`).join('')}</svg>
 <div class="node trig" style="left:2%;top:${ty}px;width:25%"><div class="nt">${ic('bolt','s')} Trigger</div><b>${esc(x.trigger)}</b><div class="np">${esc(tl)}</div></div>
 ${x.actions.map((a,i)=>`<div class="node act" style="left:39%;top:${ay(i)}px;width:24%"><div class="nt">${ic(ACTIONS[a.type]?.ic||'code','s')} Action ${i+1}</div><b>${esc(a.type)}</b><div class="np">${esc(Object.entries(a).filter(([k])=>k!=='type').map(([k,v])=>`${k}: ${v}`).join(' · ').slice(0,70))}</div></div>`).join('')||`<div class="node act" style="left:39%;top:${ty}px;width:24%;border-style:dashed"><div class="nt">Action</div><b>none yet</b><div class="np">Add one on the left</div></div>`}
 <div class="node tgt" style="left:74%;top:${ty}px;width:25%"><div class="nt">${ic(TARGETS[x.target][1],'s')} Target</div><b>${TARGETS[x.target][0].toLowerCase()}</b><div class="np">${tg.length?esc(tg.slice(0,3).join(', ')):'not installed yet'}</div></div></div>`}
function hiJSON(s){return esc(s).replace(/(&quot;(?:[^&]|&(?!quot;))*?&quot;)(\s*:)?|\b(true|false|null)\b|(-?\d+(?:\.\d+)?)/g,(m,str,colon,kw,num)=>str?(colon?`<span class="tk-p">${str}</span>${colon}`:`<span class="tk-s">${str}</span>`):kw?`<span class="tk-k">${kw}</span>`:`<span class="tk-n">${num}</span>`)}
function studioTab(x){if(PS.tab==='console')return`<div class="console" id="psC" style="min-height:300px;max-height:340px">${S.bp.logs.filter(l=>l.pid===x.id).slice(0,40).map(l=>`<div><span class="t">${ftime(l.at)}</span> <span class="${l.lvl}">●</span> ${esc(l.msg)}</div>`).join('')||'<span class="t">// Press Test run to simulate the trigger.</span>'}</div>`;
 if(PS.tab==='code')return`<div class="code"><div class="lines">${genCode(x).split('\n').map((_,i)=>i+1).join('\n')}</div><pre>${hiJS(genCode(x))}</pre></div>`;
 const j=manifest(x);return`<div class="code"><div class="lines" id="psL">${j.split('\n').map((_,i)=>i+1).join('\n')}</div><pre class="hlt" id="psH" aria-hidden="true">${hiJSON(j)}\n</pre><textarea id="psJ" spellcheck="false" aria-label="Plugin manifest">${esc(j)}</textarea></div>`}
function genCode(x){return`// Generated from manifest.json · ${x.name} v${x.version}\nimport { definePlugin } from '@mintora/blueprint'\n\nexport default definePlugin({\n  target: '${x.target}',\n  on: '${x.trigger}',\n  async run(ctx) {\n${x.actions.map(a=>`    await ctx.${a.type}(${JSON.stringify(Object.fromEntries(Object.entries(a).filter(([k])=>k!=='type')))})`).join('\n')||'    // add actions in the studio'}\n  }\n})\n`}
function hiJS(s){return esc(s).replace(/(\/\/.*)|('(?:[^'\\]|\\.)*')|(&quot;(?:[^&]|&(?!quot;))*?&quot;)|\b(import|from|export|default|async|await|const|return)\b|\b(\d+)\b/g,(m,c,s1,s2,k,n)=>c?`<span class="tk-c">${c}</span>`:s1||s2?`<span class="tk-s">${s1||s2}</span>`:k?`<span class="tk-k">${k}</span>`:`<span class="tk-n">${n}</span>`)}
function validate(o){const e=[];if(typeof o!=='object'||!o)return['The manifest must be an object'];if(!o.name||typeof o.name!=='string')e.push('"name" is required');if(!TARGETS[o.target])e.push('"target" must be page, hub or app');else if(!TRIGGERS[o.target].some(t=>t[0]===o.trigger))e.push(`"trigger" for ${o.target} must be ${TRIGGERS[o.target].map(t=>t[0]).join(' or ')}`);
 if(!Array.isArray(o.actions))e.push('"actions" must be a list');else o.actions.forEach((a,i)=>{const A=ACTIONS[a&&a.type];if(!A)e.push(`actions[${i}].type "${a&&a.type}" is unknown`);else if(A.t!==o.target)e.push(`actions[${i}] "${a.type}" does not run on ${o.target}`)});if(o.version&&!/^\d+\.\d+\.\d+$/.test(o.version))e.push('"version" must look like 1.0.0');return e}
function pluginPreview(x){if(x.target==='app')return`<div class="grid" style="gap:10px">${(()=>{const was=x.status;x.status='published';const h=pluginWidgets.call(null);x.status=was;return h})()||'<p class="muted sm">Add a metric widget.</p>'}</div>`;
 if(x.target==='hub'){const h={name:'Your hub'};const lines=x.actions.map(a=>a.type==='welcome'?['bot',fill(a.message,{name:'Ava',hub:h.name})]:a.type==='autorole'?['sys',`Ava got the ${a.role} role`]:a.type==='command'?['cmd',a.cmd,fill(a.reply,{hub:'your-hub',name:'Ava'})]:a.type==='announce'?['bot',fill(a.text,{product:'Orbit UI Kit',hub:h.name})]:['sys',a.type]);
  return`<div style="border:1px solid var(--line2);border-radius:10px;padding:10px;font-size:13px">${lines.map(l=>l[0]==='cmd'?`<div style="margin:4px 0"><b>Ava</b> <code>${esc(l[1])}</code></div><div style="margin:4px 0 8px;padding-left:10px;border-left:2px solid var(--violet)"><b style="color:var(--violet)">${esc(x.name)}</b> ${esc(l[2])}</div>`:l[0]==='bot'?`<div style="margin:4px 0;padding-left:10px;border-left:2px solid var(--violet)"><b style="color:var(--violet)">${esc(x.name)}</b> ${esc(l[1])}</div>`:`<div class="muted" style="font-style:italic;margin:4px 0">${esc(l[1])}</div>`).join('')||'<span class="muted">Add an action.</span>'}</div>`}
 const p=S.products.find(q=>q.status==='live')||S.products[0];if(!p)return'<p class="muted sm">Create a product to preview.</p>';const was=x.status,had=p.page.plugins.includes(x.id);x.status='published';if(!had)p.page.plugins.push(x.id);const out=pagePlugins(p);x.status=was;if(!had)p.page.plugins=p.page.plugins.filter(i=>i!==x.id);
 return`<div class="sf" style="${designVars(design(p.page.design).tokens)};border-radius:10px;overflow:hidden;border:1px solid var(--line2)">${out.banner}<div style="padding:16px"><b style="font-family:var(--sfont);font-size:18px">${esc(p.name)}</b><div style="margin-top:10px"><button class="sbtn" style="height:36px;font-size:13px">Get it · ${money(p.price)}</button></div>${out.proof}${out.code}</div>${out.sticky.replace('position:sticky','position:relative')}</div>`}
function installList(x){if(x.status!=='published')return`<p class="muted sm" style="margin:0">Publish the plugin to install it.</p>`;
 if(x.target==='app')return`<div class="row"><span class="grow sm">Show on my dashboard</span>${tgl(x.dash!==false,'psDash','Show on dashboard')}</div>`;
 const L=x.target==='page'?S.products.filter(p=>p.status!=='archived').map(p=>[p.id,p.name,p.page.plugins.includes(x.id)]):S.hubs.filter(h=>h.joined&&canHub(h,'manage')).map(h=>[h.id,h.name,h.plugins.includes(x.id)]);
 return L.map(([id,n,on])=>`<label class="row" style="padding:7px 0;border-bottom:1px dashed var(--line);cursor:pointer"><input type="checkbox" ${on?'checked':''} data-inst="${id}" style="accent-color:var(--mint)"><span class="grow sm">${esc(n)}</span></label>`).join('')||'<p class="muted sm">Nothing to install on yet.</p>'}
function psDash(on){const x=S.bp.plugins.find(p=>p.id===route.a[1]);x.dash=on;save();toast(on?'Widget on the dashboard':'Widget hidden','dash')}
function studioAfter(id){const x=S.bp.plugins.find(p=>p.id===id);if(!x)return;const F=$('#psF');
 const refresh=(form)=>{x.updated=Date.now();saveSoon();$('#psN').innerHTML=schematic(x);$('#psP').innerHTML=pluginPreview(x);startCountdowns();if(PS.tab==='manifest'&&form!=='json'&&$('#psJ')){const j=manifest(x);$('#psJ').value=j;$('#psH').innerHTML=hiJSON(j)+'\n';$('#psL').textContent=j.split('\n').map((_,i)=>i+1).join('\n')}else if(PS.tab==='code'){$('#psT').innerHTML=studioTab(x)}if(form==='full'||form==='json'){F.innerHTML=studioForm(x)}};
 F.oninput=e=>{const t=e.target;if(t.dataset.pf){x[t.dataset.pf]=t.value;if(t.dataset.pf==='trigger')refresh();else refresh()}else if(t.dataset.ai!=null){const a=x.actions[+t.dataset.ai];a[t.dataset.ak]=t.type==='number'?+t.value:t.value;refresh()}};F.onchange=F.oninput;
 F.onclick=e=>{const tg=e.target.closest('[data-tgt]'),rm=e.target.closest('[data-rma]');if(tg&&tg.dataset.tgt!==x.target){x.target=tg.dataset.tgt;x.trigger=TRIGGERS[x.target][0][0];x.actions=x.actions.filter(a=>ACTIONS[a.type].t===x.target);refresh('full');$('#psI').innerHTML=installList(x)}if(rm){x.actions.splice(+rm.dataset.rma,1);refresh('full')}};
 F.addEventListener('change',e=>{if(e.target.id==='psAdd'&&e.target.value){const k=e.target.value,A=ACTIONS[k],a={type:k};A.f.forEach(([f,,def,opt])=>a[f]=opt==='num'?+def:def);x.actions.push(a);refresh('full')}});
 $$('[data-pst]').forEach(b=>b.onclick=()=>{PS.tab=b.dataset.pst;$$('[data-pst]').forEach(y=>y.classList.toggle('on',y===b));$('#psT').innerHTML=studioTab(x);bindJSON()});
 const bindJSON=()=>{const J=$('#psJ');if(!J)return;const H=$('#psH'),Ln=$('#psL'),E=$('#psErr');J.onscroll=()=>{H.scrollTop=J.scrollTop;H.scrollLeft=J.scrollLeft;Ln.scrollTop=J.scrollTop};
  J.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const s=J.selectionStart;J.value=J.value.slice(0,s)+'  '+J.value.slice(J.selectionEnd);J.selectionStart=J.selectionEnd=s+2;J.oninput()}};
  J.oninput=()=>{H.innerHTML=hiJSON(J.value)+'\n';Ln.textContent=J.value.split('\n').map((_,i)=>i+1).join('\n');let o,errs;try{o=JSON.parse(J.value);errs=validate(o)}catch(err){errs=[err.message.replace(/^JSON\.parse: /,'')]}
   if(errs.length){E.style.color='#FF8A93';E.textContent='✕ '+errs[0];return}E.style.color='#7DF0B8';E.textContent='✓ valid';Object.assign(x,{name:o.name,version:o.version||x.version,desc:o.description||'',target:o.target,trigger:o.trigger,actions:o.actions});refresh('json')}};bindJSON();
 $('#psI').onchange=e=>{const t=e.target;if(!t.dataset.inst)return;const id2=t.dataset.inst;if(x.target==='page'){const p=prod(id2);p.page.plugins=t.checked?[...new Set([...p.page.plugins,x.id])]:p.page.plugins.filter(i=>i!==x.id);x.installs=S.products.filter(q=>q.page.plugins.includes(x.id)).length}else{const h=hub(id2);h.plugins=t.checked?[...new Set([...h.plugins,x.id])]:h.plugins.filter(i=>i!==x.id);x.hubInstalls=S.hubs.filter(q=>q.plugins.includes(x.id)).length}
  bpLog(x,`${t.checked?'Installed on':'Removed from'} ${x.target==='page'?prod(id2).name:hub(id2).name}`);save();$('#psN').innerHTML=schematic(x);toast(t.checked?'Installed':'Removed','plug')};startCountdowns()}
function testPlugin(id){const x=S.bp.plugins.find(p=>p.id===id),errs=validate({...JSON.parse(manifest(x))});PS.tab='console';
 if(errs.length)bpLog(x,'Test failed: '+errs[0],'err');else{bpLog(x,`Test: trigger "${x.trigger}" fired`);x.actions.forEach((a,i)=>bpLog(x,`Test: action ${i+1} ${a.type} ran in ${2+Math.floor(Math.random()*9)} ms`));if(!x.actions.length)bpLog(x,'Test: no actions to run','err')}
 save();rerender();toast(errs.length?'Test failed':'Test passed',errs.length?'x':'check')}
function bump(v){const p=String(v||'0.1.0').split('.').map(Number);p[1]++;p[2]=0;if(p[0]===0&&p[1]>=1){p[0]=1;p[1]=0}return p.join('.')}
function publishPlugin(id){const x=S.bp.plugins.find(p=>p.id===id),errs=validate(JSON.parse(manifest(x)));if(errs.length){toast(errs[0],'x');return}if(!x.actions.length){toast('Add at least one action','info');return}
 const first=x.status!=='published';x.status='published';x.version=first&&x.version.startsWith('0.')?'1.0.0':bump(x.version);x.published=x.published||Date.now();x.updated=Date.now();if(first){earn('plugin');act('plugin',`Published the ${x.name} plugin`,'bp/plugin/'+id)}bpLog(x,`Published v${x.version}`);
 if(x.target==='app'&&x.dash===undefined)x.dash=true;save();toast(first?`${x.name} published · +80 credits`:`v${x.version} published`,'rocket');rerender()}
async function delPlugin(id){const x=S.bp.plugins.find(p=>p.id===id);if(!await confirmBox(`Delete ${x.name}?`,'It is removed from every storefront and hub it runs on.',{ok:'Delete',danger:true}))return;S.bp.plugins=S.bp.plugins.filter(p=>p.id!==id);S.products.forEach(p=>p.page.plugins=p.page.plugins.filter(i=>i!==id));S.hubs.forEach(h=>h.plugins=h.plugins.filter(i=>i!==id));save();toast('Deleted','trash');go('bp/plugins')}
/* ---- designs ---- */
function bpDesigns(){return`<div class="page"><div class="ph"><div class="grow"><div class="eyebrow">${ic('palette','s')} Design Studio</div><h1>Designs</h1><p>Design systems for storefronts and hubs: colour, type, shape and texture.</p></div><div class="acts"><button class="btn mint" onclick="newDesign()">${ic('plus','s')} From scratch</button></div></div>
 <div class="pgrid" style="grid-template-columns:repeat(auto-fill,minmax(300px,1fr))">${S.bp.designs.map(d=>{const t=d.tokens,uses=S.products.filter(p=>p.page.design===d.id).length+S.hubs.filter(h=>h.design===d.id).length;return`<div class="card hov bpframe" style="overflow:hidden" onclick="go('bp/design/${d.id}')"><div class="sf ${t.pattern!=='none'?'pat-'+t.pattern:''}" style="${designVars(t)};height:150px;padding:18px;display:flex;flex-direction:column;justify-content:space-between"><b style="font-family:var(--sfont);font-size:22px;color:var(--stx)">Aa ${esc(d.name)}</b><div class="row"><span class="sbtn" style="height:32px;font-size:12px;padding:0 12px">Get it</span><span style="flex:1;height:32px;border-radius:var(--srad);background:var(--ssf)"></span></div></div>
  <div style="padding:12px 14px" class="row"><b style="font:500 14px var(--f-mono)">${esc(d.name)}</b>${d.sys?'<span class="badge" style="margin-left:6px">Built in</span>':''}<span class="xs mono muted" style="margin-left:auto">${plural(uses,'use')}</span></div></div>`}).join('')}</div></div>`}
function newDesign(){if(!licensed()){go('bp/license');return}const d={id:uid('d'),name:'Untitled design',tokens:{accent:'#6D5DFC',bg:'#FFFFFF',surface:'#F3F2FA',text:'#14121F',muted:'#6E6A80',radius:16,font:'display',pattern:'none'},sys:false,created:Date.now()};S.bp.designs.push(d);save();go('bp/design/'+d.id)}
function lum(h){const c=h.replace('#','').match(/.{2}/g).map(x=>{const v=parseInt(x,16)/255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*c[0]+.7152*c[1]+.0722*c[2]}
function contrast(a,b){try{const x=lum(a),y=lum(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05)}catch(e){return 1}}
function designStudio(id){const d=design(id);if(!d||d.id!==id)return`<div class="page"><div class="empty"><b>Design not found</b><a class="btn" href="#/bp/designs">Back</a></div></div>`;const t=d.tokens,ro=d.sys;
 const p=S.products.find(q=>q.status==='live')||S.products[0];
 return`<div class="page" style="max-width:none;padding:20px 24px 40px"><div class="row" style="margin-bottom:16px"><span style="width:38px;height:38px;border-radius:10px;display:grid;place-items:center;border:1px solid var(--line2);color:var(--mint)">${ic('palette')}</span><div><h1 style="font-size:20px">${esc(d.name)}</h1><div class="xs mono muted">${d.id}${ro?' · built in, duplicate to edit':''}</div></div>
 <div class="row" style="margin-left:auto"><button class="btn" onclick="dupDesign('${d.id}')">${ic('copy','s')} Duplicate</button>${ro?'':`<button class="btn ghost danger" onclick="delDesign('${d.id}')">${ic('trash','s')}</button><button class="btn mint" onclick="saveDesign('${d.id}')">${ic('check','s')} Save design</button>`}</div></div>
 <div class="grid" style="grid-template-columns:300px minmax(0,1fr) 280px;gap:16px;align-items:start">
 <div class="card" style="padding:16px" id="dsF"><div class="field"><label>Name</label><input class="inp" data-dk="name" value="${esc(d.name)}" ${ro?'disabled':''}></div>
  ${[['accent','Accent'],['bg','Background'],['surface','Surface'],['text','Text'],['muted','Muted text']].map(([k,n])=>`<div class="field"><label>${n}</label><div class="inp-pre"><span style="padding:0 6px"><input type="color" value="${t[k]}" data-tk="${k}" ${ro?'disabled':''} style="width:24px;height:24px;border:none;background:none;padding:0" aria-label="${n} colour"></span><input class="mono" value="${t[k]}" data-th="${k}" ${ro?'disabled':''} aria-label="${n} hex"></div></div>`).join('')}
  <div class="field"><label>Corner radius <span class="mono faint" id="dsRv">${t.radius}px</span></label><input type="range" min="0" max="28" value="${t.radius}" data-tk="radius" ${ro?'disabled':''} style="accent-color:var(--mint)"></div>
  <div class="field"><label>Typeface</label><div class="chips">${[['display','Grotesk'],['sans','Sans'],['serif','Serif'],['mono','Mono']].map(([k,n])=>`<button class="chip ${t.font===k?'on':''}" data-tf="${k}" ${ro?'disabled':''}>${n}</button>`).join('')}</div></div>
  <div class="field"><label>Texture</label><div class="chips">${[['none','None'],['grid','Grid'],['dots','Dots']].map(([k,n])=>`<button class="chip ${t.pattern===k?'on':''}" data-tp="${k}" ${ro?'disabled':''}>${n}</button>`).join('')}</div></div></div>
 <div class="card bpframe" style="padding:30px 34px;position:relative" id="dsC">${designCanvas(d,p)}</div>
 <div class="col" style="gap:16px"><div class="card" style="padding:16px"><b style="font:500 13px var(--f-mono)">CONTRAST</b><div id="dsK" style="margin-top:10px">${contrastList(t)}</div></div>
  <div class="card" style="padding:16px"><b style="font:500 13px var(--f-mono)">APPLY TO</b><div style="margin-top:10px" id="dsA">${S.products.filter(q=>q.status!=='archived').map(q=>`<label class="row" style="padding:6px 0;border-bottom:1px dashed var(--line);cursor:pointer"><input type="checkbox" data-ap="${q.id}" ${q.page.design===d.id?'checked':''} style="accent-color:var(--mint)"><span class="sm grow">${esc(q.name)}</span>${ic('page','s')}</label>`).join('')}${S.hubs.filter(h=>h.joined&&canHub(h,'manage')).map(h=>`<label class="row" style="padding:6px 0;border-bottom:1px dashed var(--line);cursor:pointer"><input type="checkbox" data-ah="${h.id}" ${h.design===d.id?'checked':''} style="accent-color:var(--mint)"><span class="sm grow">${esc(h.name)}</span>${ic('hub','s')}</label>`).join('')}</div></div>
  <div class="card" style="padding:16px"><b style="font:500 13px var(--f-mono)">TOKENS</b><pre class="mono xs" style="margin:10px 0 0;white-space:pre-wrap;color:var(--ink2)" id="dsJ">${esc(JSON.stringify(t,null,1))}</pre></div></div></div></div>`}
function designCanvas(d,p){const t=d.tokens;return`<span class="dim h" style="top:8px;left:34px;right:34px">width 100%</span><span class="dim v" style="left:8px;top:30px;bottom:30px">auto</span>
 <div class="sf ${t.pattern!=='none'?'pat-'+t.pattern:''}" style="${designVars(t)};border-radius:10px;overflow:hidden;box-shadow:0 20px 50px -20px rgba(0,8,30,.8)">
 <div style="padding:26px 28px;display:grid;grid-template-columns:1.2fr .8fr;gap:22px;align-items:center"><div><div style="font:600 11px var(--f-mono);letter-spacing:.12em;color:var(--a)">${esc(TYPES[p?.type||'template'].n.toUpperCase())}</div><h1 style="font-size:30px;margin:8px 0">${esc(p?.name||'Your product')}</h1><p style="margin:0 0 16px">${esc(p?.tagline||'A sentence that sells it.')}</p><div class="row" style="position:relative"><button class="sbtn">Get it now ${ic('arrow','s')}</button><span class="dim" style="left:0;top:50px">radius ${Math.round(t.radius*.7)}px · h 44</span></div></div>
 <div class="scov" style="position:relative">${p?cover(p,{big:1,w:320,h:240}):''}</div></div>
 <div style="padding:6px 28px 26px"><div class="sgrid">${['Fast','Complete','Loved'].map((n,i)=>`<div class="scard"><span class="sico">${ic(['bolt','layers','heart'][i])}</span><b>${n}</b><p>Text in the muted colour.</p></div>`).join('')}</div></div></div>
 <div class="row" style="margin-top:22px;gap:16px"><div style="flex:1"><div class="xs mono" style="color:#7FE3FF;margin-bottom:8px">HUB CARD</div><div class="sf" style="${designVars(t)};border-radius:var(--srad);padding:14px;display:flex;gap:12px;align-items:center"><span class="av" style="width:38px;height:38px;border-radius:calc(var(--srad)*.7);background:var(--a)">${esc(S.workspace.initials)}</span><div><b style="font-family:var(--sfont)">${esc(S.workspace.name)} hub</b><div style="font-size:12px;color:var(--smu)">#general · 28 members</div></div></div></div>
 <div style="width:220px"><div class="xs mono" style="color:#7FE3FF;margin-bottom:8px">PALETTE</div><div class="row" style="gap:6px">${['accent','bg','surface','text','muted'].map(k=>`<span data-tip="${k} ${t[k]}" style="flex:1;height:42px;border-radius:7px;background:${t[k]};box-shadow:inset 0 0 0 1px rgba(255,255,255,.2)"></span>`).join('')}</div></div></div>`}
function contrastList(t){return[['Text on background',t.text,t.bg,4.5],['Muted on background',t.muted,t.bg,3],['White on accent',  '#FFFFFF',t.accent,3],['Text on surface',t.text,t.surface,4.5]].map(([n,a,b,min])=>{const r=contrast(a,b);return`<div class="row sm" style="padding:6px 0;border-bottom:1px dashed var(--line)"><span style="width:22px;height:22px;border-radius:5px;background:${b};color:${a};display:grid;place-items:center;font-weight:700;font-size:11px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.2)">Aa</span><span class="grow">${n}</span><b class="mono">${r.toFixed(1)}</b><span class="badge ${r>=min?'live':'red'}" style="height:18px;font-size:10px">${r>=7?'AAA':r>=min?'AA':'Low'}</span></div>`}).join('')}
function designAfter(id){const d=design(id);if(!d||d.id!==id||d.sys)return bindApply(d);const F=$('#dsF'),t=d.tokens;
 const redraw=()=>{$('#dsC').innerHTML=designCanvas(d,S.products.find(q=>q.status==='live')||S.products[0]);$('#dsK').innerHTML=contrastList(t);$('#dsJ').textContent=JSON.stringify(t,null,1);$('#dsRv').textContent=t.radius+'px';d.dirty=true;saveSoon()};
 F.oninput=e=>{const x=e.target;if(x.dataset.dk){d.name=x.value;saveSoon();return}if(x.dataset.tk){t[x.dataset.tk]=x.dataset.tk==='radius'?+x.value:x.value;const h=F.querySelector(`[data-th="${x.dataset.tk}"]`);if(h)h.value=x.value;redraw()}if(x.dataset.th&&/^#[0-9a-f]{6}$/i.test(x.value)){t[x.dataset.th]=x.value;F.querySelector(`[data-tk="${x.dataset.th}"]`).value=x.value;redraw()}};
 F.onclick=e=>{const f=e.target.closest('[data-tf]'),p=e.target.closest('[data-tp]');if(f){t.font=f.dataset.tf;$$('[data-tf]',F).forEach(b=>b.classList.toggle('on',b===f));redraw()}if(p){t.pattern=p.dataset.tp;$$('[data-tp]',F).forEach(b=>b.classList.toggle('on',b===p));redraw()}};bindApply(d)}
function bindApply(d){const A=$('#dsA');if(!A||!d)return;A.onchange=e=>{const x=e.target;if(x.dataset.ap){const p=prod(x.dataset.ap);p.page.design=x.checked?d.id:'d-mint'}if(x.dataset.ah){const h=hub(x.dataset.ah);h.design=x.checked?d.id:'d-mint'}save();toast(x.checked?'Design applied':'Back to Mint Clean','palette')}}
function saveDesign(id){const d=design(id);const first=!d.saved;d.saved=true;d.dirty=false;if(first){earn('design');act('plugin',`Saved the ${d.name} design`)}save();toast(first?'Design saved · +40 credits':'Design saved','check')}
function dupDesign(id){if(!licensed()){go('bp/license');return}const d=design(id),n={...JSON.parse(JSON.stringify(d)),id:uid('d'),name:d.name+' copy',sys:false,saved:false};S.bp.designs.push(n);save();go('bp/design/'+n.id)}
async function delDesign(id){const d=design(id);if(!await confirmBox(`Delete ${d.name}?`,'Pages and hubs using it go back to Mint Clean.',{ok:'Delete',danger:true}))return;S.bp.designs=S.bp.designs.filter(x=>x.id!==id);S.products.forEach(p=>{if(p.page.design===id)p.page.design='d-mint'});S.hubs.forEach(h=>{if(h.design===id)h.design='d-mint'});save();go('bp/designs')}
/* ---- license page ---- */
function bpLicense(){const L=S.bp.license;return`<div class="page"><div class="ph"><div class="grow"><div class="eyebrow">${ic('key','s')} License</div><h1>Blueprint license</h1><p>One license unlocks Plugin Studio and Design Studio for your workspace. It never expires.</p></div></div>
 ${L?`<div class="lic bpframe" style="max-width:760px"><div class="row">${bpMark(44)}<div><b style="font:500 18px var(--f-mono)">Mintora Blueprint · ${L.tier.toUpperCase()}</b><div style="color:#8FB3F0;font:500 12px var(--f-mono)">Issued ${fdate(L.at)} to ${esc(S.workspace.name)} · ${plural(L.seats,'seat')}</div></div><span class="badge live" style="margin-left:auto">Active</span></div>
  <div style="margin:26px 0 8px;color:#8FB3F0;font:500 11px var(--f-mono);letter-spacing:.1em">LICENSE KEY</div><div class="row"><span class="key" id="lkV">${L.key.replace(/[A-Z0-9](?=[A-Z0-9-]{4})/g,(c,i)=>i>6?'•':c)}</span><button class="btn sm" style="margin-left:auto" onclick="$('#lkV').textContent='${L.key}'">${ic('eye','s')} Show</button><button class="btn sm" onclick="copyText('${L.key}')">${ic('copy','s')} Copy</button></div>
  <div class="grid g3 mt2" style="gap:12px">${[['Plugin Studio','Storefront, hub and dashboard plugins'],['Design Studio','Design systems from scratch'],['Console and API','Test runs, logs, the full reference']].map(([a,b])=>`<div style="border:1px dashed rgba(160,195,255,.35);border-radius:10px;padding:12px"><b style="font:500 13px var(--f-mono)">${a}</b><div style="color:#A8BFE8;font-size:12.5px;margin-top:4px">${b}</div></div>`).join('')}</div></div>`
 :`<div class="grid g2" style="max-width:980px">${[['solo','Solo','For one maker',2000,['Plugin Studio','Design Studio','Unlimited plugins and designs','1 seat']],['studio','Studio','For a team',null,['Everything in Solo','5 seats','Priority review for the plugin directory','Enter a key from your team admin']]].map(([k,n,s,c,f])=>`<div class="lic bpframe"><div class="row">${bpMark(36)}<b style="font:500 20px var(--f-mono)">${n}</b><span style="margin-left:auto;color:#8FB3F0;font:500 12px var(--f-mono)">${s}</span></div>
  <div style="font:500 30px var(--f-mono);margin:18px 0 6px;color:#7FE3FF">${c?`${nfmt(c)} <span style="font-size:14px;color:#8FB3F0">credits</span>`:'License key'}</div><ul style="list-style:none;padding:0;margin:0 0 20px;color:#C5D6F5;font-size:13.5px">${f.map(x=>`<li style="padding:5px 0;display:flex;gap:8px">${ic('check','s')}${x}</li>`).join('')}</ul>
  ${c?`<button class="btn mint full lg" onclick="buyLicense()" ${S.credits.balance<c?'disabled':''}>${ic('key','s')} Unlock with ${nfmt(c)} credits</button><div style="margin-top:8px;font:500 11.5px var(--f-mono);color:#8FB3F0;text-align:center">You have ${nfmt(S.credits.balance)} credits${S.credits.balance<c?` · ${nfmt(c-S.credits.balance)} to go`:''}</div>`
  :`<div class="inp-pre" style="border-color:rgba(160,195,255,.35)"><span>${ic('key','s')}</span><input id="bpKey" class="mono" placeholder="MNT-BP-XXXX-XXXX-XXX" autocomplete="off" spellcheck="false" onkeydown="if(event.key==='Enter')enterKey()"></div><div id="bpKeyE" style="color:#FF8A93;font-size:12px;min-height:18px;margin-top:6px"></div><button class="btn full lg" style="background:#EAF1FF;color:#0C2A66;border-color:#EAF1FF" onclick="enterKey()">Activate key</button>`}</div>`).join('')}</div>`}</div>`}
/* ---- reference ---- */
function bpDocs(){const code=(t,s)=>`<div class="code" style="margin:10px 0 18px"><pre style="min-height:0;padding-left:14px;color:#D9E6FF">${t==='json'?hiJSON(s):hiJS(s)}</pre></div>`;
 return`<div class="page" style="max-width:980px"><div class="eyebrow">${ic('code','s')} Reference</div><h1>Blueprint reference</h1><p class="muted">Everything a plugin can do, and the API your own apps can call.</p>
 <div class="card" style="padding:22px 24px;margin-top:20px"><h2>Manifest</h2><p class="muted sm">A plugin is a manifest: where it runs, what triggers it, and what it does.</p>${code('json',JSON.stringify({name:'Launch countdown',version:'1.0.0',target:'page',trigger:'load',actions:[{type:'banner',text:'Launch week pricing',tone:'accent'},{type:'countdown',label:'Ends in',hours:48}]},null,2))}
 <h3>Targets and triggers</h3><table class="tbl" style="margin:10px 0 18px"><thead><tr><th>Target</th><th>Triggers</th><th>Actions</th></tr></thead><tbody>${Object.entries(TARGETS).map(([k,[n]])=>`<tr><td><code>${k}</code> <span class="muted">${n}</span></td><td>${TRIGGERS[k].map(t=>`<code>${t[0]}</code>`).join(' ')}</td><td>${Object.entries(ACTIONS).filter(([,a])=>a.t===k).map(([a])=>`<code>${a}</code>`).join(' ')}</td></tr>`).join('')}</tbody></table>
 <h3>Action fields</h3><table class="tbl" style="margin:10px 0 18px"><tbody>${Object.entries(ACTIONS).map(([k,a])=>`<tr><td><code>${k}</code></td><td class="muted sm">${a.f.map(f=>`<code>${f[0]}</code> ${esc(f[1])}`).join(' · ')}</td></tr>`).join('')}</tbody></table>
 <h3>Placeholders</h3><p class="muted sm"><code>{name}</code> the member's first name · <code>{hub}</code> the hub · <code>{product}</code> the product · <code>{n}</code> purchases this week.</p></div>
 <div class="card" style="padding:22px 24px;margin-top:16px"><h2>REST API</h2><p class="muted sm">Authenticate with a key from Settings, sent as <code>Authorization: Bearer mk_live_…</code>.</p>
 <table class="tbl" style="margin:10px 0 18px"><tbody>${[['GET','/v1/products','List products'],['GET','/v1/products/:id','One product with its storefront'],['GET','/v1/orders?since=','Orders, newest first'],['POST','/v1/licenses/verify','Check a customer license key'],['GET','/v1/hubs/:id/members','Members and roles'],['POST','/v1/hubs/:id/messages','Post as your plugin']].map(([m,p,d])=>`<tr><td style="width:70px"><span class="badge ${m==='GET'?'blue':'live'}">${m}</span></td><td><code>${p}</code></td><td class="muted sm">${d}</td></tr>`).join('')}</tbody></table>
 ${code('js',`// Verify a license key from your own app\nconst res = await fetch('https://api.mintora.shop/v1/licenses/verify', {\n  method: 'POST',\n  headers: { Authorization: 'Bearer mk_live_…', 'Content-Type': 'application/json' },\n  body: JSON.stringify({ key: 'MNT-7Q2K-91LD-4821' })\n})\nconst { valid, product, order } = await res.json()`)}
 <h3>Webhooks</h3><p class="muted sm">Events: <code>order.created</code> <code>refund.created</code> <code>product.published</code> <code>hub.member_joined</code>. Each request carries a <code>Mintora-Signature</code> header: an HMAC-SHA256 of the body with your signing secret.</p></div></div>`}
